    if (paths.isEmpty) {
      _refHashes.remove(dirId);
      return app;
    }
    final contents = <String, String>{};
    final digests = <String, String>{};
    for (final path in paths) {
      final content = (await _env.readTextFile('${app.dir}/$path')).valueOrNull;
