Future<List<String>> listAppDirIds() async {
  final entries = (await _env.listDir('apps')).valueOrNull ?? const [];
  return [
    for (final entry in entries)
      if (entry.kind == FileKind.directory && !entry.name.startsWith('.'))
        entry.name,
  ];
}

