      AppLog.i('apps', 'demo seed failed: $id — $e');
      failedSeeds.value = {...failedSeeds.value, id: e.toString()};
      continue;
    }
    failedSeeds.value = {...failedSeeds.value}..remove(id);
  }
  if (hashesChanged) {
    await _env.writeFile(demoSeedsFile, jsonEncode(hashes));
