      if (streamingBubble && ev.role === 'assistant') {
        streamingBubble.textContent = ev.text ?? streamingBubble.textContent;
        streamingBubble = null;
      } else if (ev.role === 'user') {
        // Replay/live user rows carry the SW's per-turn `[context] …`
