          ? JsTileWidgetInfo.fromJson(widget)
          : null,
      declaredPermissions: AppPermissions.fromJson(json),
      bundled: bundled,
      platforms: json.containsKey('platforms')
          ? _platformList(json['platforms'])
          : null,
    );
  }

