    if (_scriptChecked) return;
    if (!_fahFsGetAllDefined.toDart) {
      await _injectFsStoreScript();
    }
    _scriptChecked = _fahFsGetAllDefined.toDart;
    if (!_scriptChecked) {
      throw StateError(
        'fs_store.js is not loaded: add <script src="fs_store.js">'
