          return _AddAppTile(
            colors: colors,
            theme: theme,
            isLight: isLight,
            onTap: onAdd,
          );
        }
        return _AppTile(
          app: apps[index],
          onTap: () => onTap(apps[index]),
          onLongPress: onLongPress == null
              ? null
              : (position) => onLongPress!(apps[index], position),
