  // explicitly (missing files are fine).
  for (final metaFile in const [
    installedMetaFile,
    demoSeedsFile,
    'apps/.catalog_cache_v2.json',
  ]) {
    try {
      await _env.remove(metaFile, recursive: true);
    } on Object {
      // Absent or read-only — nothing to reset there.
