    dir,
    manifest,
    errors,
    warnings,
    errors.isEmpty
        ? [
            for (final file in files)
              (
                path:
                    p.relative(file.path, from: dir.path).replaceAll('\\', '/'),
                bytes: file.readAsBytesSync(),
              ),
          ]
        : null,
    null,
  );
}

