    widget.manager.removeListener(_onManagerChanged);
    _searchController.removeListener(_onSearchChanged);
    _searchController.dispose();
    _detachFsRevision();
    _layout?.removeListener(_onLayoutChanged);
    _layoutReloadDebounce?.cancel();
    _cancelFolderDwell();
    super.dispose();
  }

