    if (!mounted || _layout != null) return;
    setState(() {
      _layout = store..addListener(_onLayoutChanged);
    });
    _syncApps();
  }

  void _onManagerChanged() {
    _attachFsRevision();
    if (mounted) setState(() {});
  }

