/// Reconciles the persisted layout with the discovered apps (new apps
/// append, deleted apps vanish, empty folders dissolve).
void _syncApps() {
  final apps = _apps;
  if (apps == null) return;
  _layout?.syncApps(apps.map((app) => app.id));
}

