  if (text == null) return {};
  final decoded = jsonDecode(text);
  return {
    for (final entry in (decoded as Map).entries)
      entry.key as String: {
        for (final field in (entry.value as Map).entries)
          field.key as String: field.value.toString(),
      },
  };
}

