                                final target = _backgroundTarget;
                                if (target != null) {
                                  _onDrop(
                                    details.data,
                                    target.$1,
                                    details.offset,
                                  );
                                }
                              },
                              builder: (context, _, _) =>
                                  const SizedBox.expand(),
                            );
                          },
                        ),
                      ),
                      for (var i = 0; i < keys.length; i++)
                        AnimatedPositioned(
