  );
}

Future<MemoryExecutionEnv> _seededEnv() async {
  final env = MemoryExecutionEnv();
  await env.writeFile('apps/alpha/manifest.json', _customManifest);
  await env.writeFile(
    'apps/alpha/widget.js',
    '(function(){ jsr.render({type:"text",data:"hi"}); })();',
