const _allowlist = <String, List<String>>{
  'lib/ui/screens/settings.dart': ['https://example.com/v1'],
};

final _textPattern = RegExp(
  '''Text\\(\\s*['"]([^'"]*[A-Za-zА-Яа-я][^'"]*)['"]''',
);
final _decorationPattern = RegExp(
