      final override = _layout?.tileSizeFor(appId);
      final w = override?.w ?? tile.widthCells;
      final h = override?.h ?? tile.heightCells;
      return (w: w.clamp(1, crossAxisCount), h: h);
    }
  }
  return (w: 1, h: 1);
}

