TileSpan? _effectiveTileSpan(String appId) {
  final tile = _appsById[appId]?.tileWidget;
  if (tile == null) return null;
  final override = _layout?.tileSizeFor(appId);
  return (
    w: override?.w ?? tile.widthCells,
    h: override?.h ?? tile.heightCells,
  );
}

