    tester,
  ) async {
    final (env, _) = await _pump(tester, _StubPicker({}));
    await tester.tap(find.text('load'));
    await tester.pumpAndSettle();

    expect(find.byType(AlertDialog), findsNothing);
    expect((await env.listDir('apps')).valueOrNull ?? const [], isEmpty);
  });

