  testWidgets('AC1: valid folder → confirm → installed, grid refreshes', (
    tester,
  ) async {
    final (env, manager) = await _pump(tester, _StubPicker(goodFolder()));
    manager.active!.service.fsRevision.value = 0;
    await tester.tap(find.text('load'));
