    var files = normalizePaths(pickedFiles, errors);
    if (errors.isNotEmpty) {
      return WidgetPayloadValidation(
        files: const {},
        manifest: null,
        errors: errors,
        warnings: warnings,
      );
    }
    files = stripCommonRoot(files);

