                            opacity: 0.35,
                            child: _tileContent(
                              colors,
                              tile,
                              LauncherGridSpec.spacing,
                            ),
                          ),
                          child: _tileContent(
                            colors,
                            tile,
                            LauncherGridSpec.spacing,
                          ),
                        ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

