Uint8List widgetZip(String id) {
  final archive = Archive();
  final data = {
    '$id/manifest.json': utf8.encode('{"id":"$id","name":"$id"}'),
    '$id/widget.js': utf8.encode('(function(){$id();})();'),
    '$id/icon.svg': utf8.encode('<svg>$id</svg>'),
