      Icons.folder_outlined,
      size: size * 0.5,
      color: colors.dim,
    ),
    _ when LauncherLayoutStore.isFolderKey(key) => _folderMiniIcons(
      colors,
      LauncherLayoutStore.folderIdOf(key),
      size,
    ),
    _ => Center(

                              child: _maybeSeedErrorBadge(
