    });

    test('schema breaks carry the catalog engine strings verbatim', () {
      final result = const WidgetPayloadValidator().validate({
        'manifest.json': utf8.encode(jsonEncode({'version': '1.0.0'})),
        'widget.js': utf8.encode('x'),
