  /// object.
  final Map<String, Object?>? manifest;

  final List<WidgetPayloadError> errors;
  final List<WidgetPayloadWarning> warnings;

  /// True when nothing blocks the load — warnings never do.
  bool get isValid => errors.isEmpty;
}

