    if (manifestBytes == null) {
      errors.add(
        const WidgetPayloadError(
          'manifest_missing',
          'manifest.json not found in the picked folder — a widget is a '
          'folder with manifest.json and widget.js at its root',
        ),
      );
    } else {
      manifest = _decodeManifest(manifestBytes, errors);
      if (manifest != null) {
        _checkSchema(manifest, errors, warnings);
