/// Problem types shared by validation and building.
library;

/// A problem found while inspecting the widget tree.
///
/// [ValidationError] blocks publishing; [ValidationWarning] does not
/// (forward compatibility / advice only).
sealed class ValidationIssue {
  ValidationIssue(this.message);

  /// Human-readable description, prefixed with the widget directory.
  final String message;

  @override
  String toString() => message;
}

final class ValidationError extends ValidationIssue {
  ValidationError(super.message);
}

final class ValidationWarning extends ValidationIssue {
  ValidationWarning(super.message);
}

/// Thrown when parsing a manifest fails structurally (not valid JSON object
/// or a hard-required field is unusable).
final class ManifestException implements Exception {
  ManifestException(this.errors);

  final List<String> errors;

  @override
  String toString() => 'ManifestException: ${errors.join('; ')}';
}

/// The strict semver subset accepted for widget versions: `X.Y.Z`.
final RegExp _semverRegExp = RegExp(
  r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$',
);

/// Whether [value] is a strict `X.Y.Z` semver string.
bool isValidSemver(String value) => _semverRegExp.hasMatch(value);

{"path":"flutter_app/test/apps/widget_payload_validator_test.dart","content":"// Copyright (c) 2026, the Flutter Agent Harness authors.
// Use of this source code is governed by a MIT license that can be found
// in the LICENSE file.

// Unit tests for the shared widget payload validator (gh-1616 UT-*): the
// one ruleset the unpacked loader (and #1614-style storage reads) run over
// an in-memory `apps/<id>/` payload BEFORE anything is written to the env.
//
// The manifest schema strings are byte-identical with the fa_widgets
// catalog engine (the same `WidgetManifest` parser the catalog CI runs —
// issue #1045's one-ruleset invariant), so a payload rejected here is
// rejected there with the same words.

import 'dart:convert';
import 'dart:typed_data';

import 'package:fa/apps/widget_payload_validator.dart';
import 'package:flutter_test/flutter_test.dart';

WidgetPayloadValidation validate(Map<String, Object?> manifest,
    {Map<String, String>? extra, Map<String, Uint8List>? files}) {
  return const WidgetPayloadValidator().validate(
    files ??
        {
          'manifest.json': utf8.encode(jsonEncode(manifest)),
          'widget.js': utf8.encode('jsr.render({type:"text",data:"hi"});'),
          ...?extra?.map((k, v) => MapEntry(k, utf8.encode(v))),
        },
  );
}

void main() {
  group('WidgetPayloadValidator — valid payloads', () {
    test('minimal manifest.json + widget.js passes', () {
      final result = validate({
        'id': 'fa-agents',
        'name': 'FA Agents',
        'version': '1.2.3',
      });
      expect(result.isValid, isTrue, reason: '${result.errors}');
      expect(result.manifest?['id'], 'fa-agents');
      expect(result.id, 'fa-agents');
      expect(result.network, isFalse);
      expect(result.allowedCommands, isEmpty);
    });

    test('multi-file payload (helper modules) passes with 2+ files', () {
      final result = validate(
        {
          'id': 'my-widget',
          'name': 'My Widget',
          'version': '0.1.0',
        },
        extra: {
          'lib/helpers.js': "import './deep/more.js';",
          'lib/deep/more.js': 'export const x = 1;',
        },
      );
      expect(result.isValid, isTrue, reason: '${result.errors}');
      expect(result.files.keys, containsAll(['lib/helpers.js', 'widget.js']));
    });

    test('every id matching [a-z0-9][a-z0-9-]{1,31} passes', () {
      for (final id in ['ab', 'a1', 'fa-agents', 'a${'b' * 31}']) {
