    final tileEntry = switch (manifest?['widget']) {
      final Map<Object?, Object?> widget => widget['entry']?.toString(),
      _ => null,
    };
    if (tileEntry != null &&
        tileEntry.isNotEmpty &&
        tileEntry != entryFile &&
        !files.containsKey(tileEntry)) {
      errors.add(
        WidgetPayloadError(
          'tile_entry_missing',
          'declared tile entry "$tileEntry" not found in the picked folder',
