  /// write-verify below.
  Future<void> installWidget({
    required String id,
    required String version,
    required Map<String, Uint8List> files,
  }) async {
    await _validateI18nRefs(id, files);
    final meta = await _readInstalled();
    final entry = meta.putIfAbsent(
