  static String? _sharedRootOf(Map<String, Uint8List> files) {
    String? root;
    for (final path in files.keys) {
      final slash = path.indexOf('/');
      if (slash <= 0) return null;
      final first = path.substring(0, slash);
      if (root == null) {
        root = first;
      } else if (root != first) {
        return null;
      }
    }
