                  'fa-agents/widget.js': utf8.encode('jsr.render(null);'),
                }),
              ),
              child: const Text('load'),
            ),
          ),
        ),
      ),
    );
    await tester.tap(find.text('load'));
    await tester.pumpAndSettle();
    // ignore: avoid_print
    print('DEBUG dialogs=${find.byType(Dialog).evaluate().length}');
    // ignore: avoid_print
    print('DEBUG replace-note=${find.textContaining('2.0.0').evaluate().length}');
  });
}
