/// Golden coverage for the fa_widgets catalog sheet (`WidgetsCatalogSheet`):
/// the loaded-catalog grid and the offline/error state.
///
/// The catalog HTTP layer is a MockClient, so the sheet renders offline-safe
/// with real fonts and the app theme.
library;

import 'dart:convert';

import 'package:fa/apps/widgets_catalog_sheet.dart';
import 'package:flutter/material.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:http/http.dart' as http;
import 'package:http/testing.dart';

import 'golden_test_helper.dart';

http.Client _catalogServer() => MockClient((req) async {
  final name = req.url.pathSegments.last;
  if (name == 'catalog.json') {
    return http.Response(
      jsonEncode({
        'widgets': [
          {
            'id': 'focus-timer',
            'name': 'Focus Timer',
            'version': '1.2.0',
            'description': 'Pomodoro timer with long breaks',
            'tags': ['timer'],
            'permissions': {'network': false, 'allowedCommands': []},
            'zip': {'file': 'focus-timer-1.2.0.zip'},
          },
          {
            'id': 'unit-convert',
            'name': 'Unit Converter',
            'version': '0.9.1',
            'description': 'Length, mass and temperature in one tile',
            'tags': ['tools'],
            'permissions': {'network': false, 'allowedCommands': []},
            'zip': {'file': 'unit-convert-0.9.1.zip'},
          },
        ],
      }),
      200,
    );
  }
  return http.Response('nf', 404);
});

void main() {
  setUpAll(ensureGoldenFonts);

  Future<void> pumpSheet(
    WidgetTester tester,
    http.Client client,
    Size size,
  ) async {
    await pumpGolden(
      tester,
      SizedBox(
        width: 420,
        height: 700,
        child: WidgetsCatalogSheet(
          env: MemoryExecutionEnv(),
          httpClient: client,
        ),
      ),
      size: size,
    );
  }

  testWidgets('widgets catalog sheet lists installable entries', (
    tester,
  ) async {
    await pumpSheet(tester, _catalogServer(), goldenSizeTall);
    await expectGolden(tester, 'widgets_catalog_sheet');
  });

  testWidgets('widgets catalog sheet shows the offline error state', (
    tester,
  ) async {
    // A 404 for everything: the sheet surfaces its could-not-load state.
    await pumpSheet(
      tester,
      MockClient((req) async => http.Response('nf', 404)),
      goldenSizeTall,
    );
    await expectGolden(tester, 'widgets_catalog_sheet_error');
  });

Future<void> pumpGolden(
  WidgetTester tester,
  Widget child, {
  Size size = goldenSizeTall,
  Locale locale = const Locale('en'),
  ThemeData? theme,
  Widget Function(Widget child)? wrap,

  /// False for frames with infinite animations (spinners): settles by
  /// pumping one frame instead of pumpAndSettle, which would time out.
  bool settle = true,
}) async {
  tester.view.physicalSize = size;
  tester.view.devicePixelRatio = 1.0;
  addTearDown(tester.view.reset);
  await tester.pumpWidget(
    MaterialApp(
      debugShowCheckedModeBanner: false,
      theme: theme ?? buildFahTheme(),
      locale: locale,
      localizationsDelegates: AppLocalizations.localizationsDelegates,
      supportedLocales: AppLocalizations.supportedLocales,
      home: wrap != null ? wrap(child) : Scaffold(body: Center(child: child)),
    ),
  );
  if (settle) {
    await tester.pumpAndSettle();
  } else {
    await tester.pump();
  }
  expectRealFontText(tester);
}

/// Asserts the current frame matches `test/golden/goldens/<name>.png`.
Future<void> expectGolden(WidgetTester tester, String name) {
  return expectLater(
    find.byType(MaterialApp),
    matchesGoldenFile('goldens/$name.png'),
  );
}

/// Fails when any visible text is painted with the test fallback font.
///
/// A [TextStyle] that REPLACES a themed label style (ButtonStyle.textStyle,
/// `styleFrom(textStyle: …)`, snackbar/tooltip content styles) drops the
/// themed fontFamily, and the engine then paints the glyphs with its default
/// font — solid Ahem placeholder blocks in goldens, a foreign system font on
/// devices (issue #947). Every themed style carries an explicit family (the
/// textTheme is built with `.apply(fontFamily: …)`), so a null family on a
/// rendered paragraph is always this bug.
void expectRealFontText(WidgetTester tester) {
  final offenders = <String>{};
  for (final renderObject
      in tester.allRenderObjects.whereType<RenderParagraph>()) {
    final plain = renderObject.text.toPlainText().trim();
    final family = renderObject.text.style?.fontFamily;
    if (plain.isNotEmpty && (family == null || family.isEmpty)) {
      offenders.add(
        '"${plain.length > 40 ? '${plain.substring(0, 40)}…' : plain}"',
      );
    }
  }
  if (offenders.isNotEmpty) {
    fail(
      'Text painted with the test fallback font (family-less resolved '
      'TextStyle — add fontFamily to the overriding style, mirroring the '
      'button themes in app_theme.dart): ${offenders.take(10).join(', ')}',
    );
  }
}

